import{_ as e,o as a,c as o,a5 as s}from"./chunks/framework.C588jwcu.js";const u=JSON.parse('{"title":"Change Actor State","description":"","frontmatter":{"title":"Change Actor State","order":4},"headers":[],"relativePath":"en/latest/tutorial/script/actor/actor-change-state.md","filePath":"en/latest/tutorial/script/actor/actor-change-state.md","lastUpdated":1785683504000}'),r={name:"en/latest/tutorial/script/actor/actor-change-state.md"};function n(i,t,d,c,h,l){return a(),o("div",null,[...t[0]||(t[0]=[s('<h1 id="change-actor-state" tabindex="-1">Change Actor State <a class="header-anchor" href="#change-actor-state" aria-label="Permalink to &quot;Change Actor State&quot;">​</a></h1><h2 id="description" tabindex="-1">Description <a class="header-anchor" href="#description" aria-label="Permalink to &quot;Description&quot;">​</a></h2><p>Switch the state of the specified actor. By default, Konado fades out the current state, applies the new state, fades it in, and resumes the story after the transition finishes.</p><h2 id="syntax" tabindex="-1">Syntax <a class="header-anchor" href="#syntax" aria-label="Permalink to &quot;Syntax&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>actor change &lt;character name&gt; &lt;new state&gt;</span></span></code></pre></div><h2 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;Parameters&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Required</th><th>Example</th><th>Description</th></tr></thead><tbody><tr><td>Character</td><td>Yes</td><td>kona</td><td>Name of the actor whose state should be changed</td></tr><tr><td>New state</td><td>Yes</td><td>happy</td><td>New state to switch to</td></tr></tbody></table><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>actor change kona happy</span></span></code></pre></div><h2 id="state-transition" tabindex="-1">State transition <a class="header-anchor" href="#state-transition" aria-label="Permalink to &quot;State transition&quot;">​</a></h2><p>The default <code>actor change</code> sequence is:</p><ol><li>Fade out the current actor.</li><li>Apply the new state to the character scene.</li><li>Fade in the actor with the new state.</li><li>Continue with the next story command after the transition finishes.</li></ol><p>Configure the transition in the Inspector for the <code>KND_ActingInterface</code> node:</p><table tabindex="0"><thead><tr><th>Property</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>enable_actor_state_fade</code></td><td><code>true</code></td><td>Enables the fade transition for actor state changes</td></tr><tr><td><code>actor_state_fade_duration</code></td><td><code>0.3</code></td><td>Total transition duration in seconds; fade-out and fade-in each use half</td></tr></tbody></table><p>Disable <code>enable_actor_state_fade</code> or set <code>actor_state_fade_duration</code> to <code>0</code> to switch states immediately.</p><p>The transition fades the stable character mount and does not duplicate the character scene, so the same flow supports textures, video, Spine, Live2D, and custom character scenes. If the target actor is missing or its scene cannot apply the state, Konado completes the command and continues the story instead of waiting indefinitely.</p>',16)])])}const f=e(r,[["render",n]]);export{u as __pageData,f as default};
